export function sha256(data) {
  const buf = Buffer.isBuffer(data) ? data : Buffer.from(String(data), 'utf8');
  return crypto.createHash('sha256').update(buf).digest('hex');
}

export function isUtf8ContinuationByte(byte) {
  return (byte & 0xC0) === 0x80;
}

export function isCodepointBoundary(buf, offset) {
  if (offset < 0 || offset > buf.length) return false;
  if (offset === 0 || offset === buf.length) return true;
  return !isUtf8ContinuationByte(buf[offset]);
}

export class VixenCyberneticsEngine {
  constructor(options = {}) {
    this.estateCensus = { ...ORIGINAL_EM_ESTATE_CENSUS };
    this.recipientCensus = { ...LATER_EXPERIMENT_A_RECIPIENT_CENSUS };
    this.instruments = [...DOCUMENTARY_INSTRUMENTS_21];
    this.humanGates = [...HUMAN_IDENTITY_GATES];
    this.documents = new Map();
    this.heldStates = new Map();
    this.options = options;

    this.initPreservedUncertainty();
  }

  initPreservedUncertainty() {
    this.heldStates.set('ORIGINAL_EXECUTOR', {
      status: 'HELD_ORIGINAL_VIXEN_EXECUTOR_ABSENT',
      reason: 'No original standalone executable recovered in repository lineage.',
