  // --- 1. Source-Sensitive Navigation ---
  getNavigationSummary() {
    return {
      canonical_route: CANONICAL_VIXEN_ROUTE,
      canonical_signature: CANONICAL_VIXEN_SIGNATURE,
      original_em_estate: {
        total_sources: this.estateCensus.original_sources,
        total_derivatives: this.estateCensus.extracted_derivatives,
        negative_extraction_states: this.estateCensus.negative_extraction_states,
        appledouble_count: this.estateCensus.appledouble_sidecars,
        unsupported_count: this.estateCensus.unsupported_format_archives,
        work_route_interval: this.estateCensus.work_route_interval,
        human_identity_gates_count: this.estateCensus.human_identity_gates,
        partition_possibilities: this.estateCensus.identity_partitions_count,
        standalone_executors: this.estateCensus.standalone_scientific_executors_recovered,
      },
      later_experiment_a_recipient: {
        total_records: this.recipientCensus.total_records,
        original_sources: this.recipientCensus.original_sources,
        additional_original_documents: this.recipientCensus.additional_original_documents,
        extracted_derivatives: this.recipientCensus.extracted_derivatives,
        distinct_from_original_estate: true,
      },
    };
  }

  // --- 2. Work Identity & Human Gate Partition Evaluation ---
  evaluateWorkIdentityPartitions(customResolutions = null) {
    if (customResolutions && Object.keys(customResolutions).length > 0) {
      // If someone attempts to resolve the gate algorithmically, refuse unless explicitly authorized
      const error = new Error('UNAUTHORIZED_HUMAN_GATE_RESOLUTION: Machine agents cannot autonomously resolve identity gates.');
      error.code = 'UNAUTHORIZED_HUMAN_GATE_RESOLUTION';
      throw error;
    }

    const partitions = [];
    // 2^8 = 256 partitions
    const numGates = this.humanGates.length;
    const totalCombinations = 1 << numGates;

    for (let i = 0; i < totalCombinations; i++) {
      let activeSplits = 0;
      const gateStates = {};

      for (let g = 0; g < numGates; g++) {
        const isSplit = Boolean((i >> g) & 1);
        const gate = this.humanGates[g];
        gateStates[gate.gate_id] = isSplit ? 'SEPARATE_WORK_SUPPORTED' : 'SAME_WORK_SUPPORTED';
        if (isSplit) activeSplits++;
      }

      const calculatedWorkCount = 32 + activeSplits; // 32 base + up to 8 splits = [32, 40]
      partitions.push({
        partition_index: i,
        gate_states: gateStates,
        active_splits: activeSplits,
        effective_work_count: calculatedWorkCount,
      });
    }

    return {
      total_partitions_evaluated: partitions.length,
      work_count_min: 32,
      work_count_max: 40,
      human_closure_status: 'RESERVED_FOR_OPERATOR',
      partitions_sample: partitions.slice(0, 4), // provide sample
    };
  }

  // --- 3. Original Document Retrieval & Exact Passage Witness ---
  admitDocument(docId, title, contentUtf8, classification = 'SOURCE_FREE_DEMONSTRATION_RECORD') {
    const rawBuffer = Buffer.from(contentUtf8, 'utf8');
    const digest = sha256(rawBuffer);

    this.documents.set(docId, {
      doc_id: docId,
      title,
      classification,
      byte_length: rawBuffer.length,
      sha256: digest,
      raw_buffer: rawBuffer,
      text: contentUtf8,
    });

    return {
      doc_id: docId,
      title,
      classification,
      is_authenticated_original_source: classification === 'ORIGINAL_SOURCE',
      byte_length: rawBuffer.length,
      sha256: digest,
      status: 'ADMITTED',
    };
  }

  retrievePassageWitness(docId, byteStart, byteEnd) {
    const doc = this.documents.get(docId);
    if (!doc) {
      const err = new Error(`DOCUMENT_NOT_FOUND: Document ${docId} has not been admitted.`);
      err.code = 'DOCUMENT_NOT_FOUND';
      throw err;
    }

    if (byteStart < 0 || byteEnd > doc.raw_buffer.length || byteStart >= byteEnd) {
      const err = new Error(`INVALID_SPAN: Requested span [${byteStart}, ${byteEnd}] is out of bounds for document length ${doc.raw_buffer.length}.`);
      err.code = 'INVALID_SPAN';
      throw err;
    }

    // Enforce UTF-8 codepoint boundary safety
    if (!isCodepointBoundary(doc.raw_buffer, byteStart)) {
      const err = new Error(`INVALID_UTF8_BOUNDARY: byteStart ${byteStart} lands on a UTF-8 continuation byte (0x${doc.raw_buffer[byteStart].toString(16).toUpperCase()}). Mid-codepoint slicing refused.`);
      err.code = 'INVALID_UTF8_BOUNDARY';
      throw err;
    }
    if (!isCodepointBoundary(doc.raw_buffer, byteEnd)) {
      const err = new Error(`INVALID_UTF8_BOUNDARY: byteEnd ${byteEnd} lands on a UTF-8 continuation byte (0x${doc.raw_buffer[byteEnd].toString(16).toUpperCase()}). Mid-codepoint slicing refused.`);
      err.code = 'INVALID_UTF8_BOUNDARY';
      throw err;
    }

    const sliceBuf = doc.raw_buffer.subarray(byteStart, byteEnd);
    const sliceText = sliceBuf.toString('utf8');
    const sliceSha256 = sha256(sliceBuf);

    return {
      doc_id: docId,
      classification: doc.classification,
      is_authenticated_original_source: doc.classification === 'ORIGINAL_SOURCE',
      admonition: doc.classification === 'SOURCE_FREE_DEMONSTRATION_RECORD'
        ? 'DEMONSTRATION RECORD ONLY — No authenticated original sources admitted.'
        : null,
      byte_start: byteStart,
      byte_end: byteEnd,
      byte_count: sliceBuf.length,
      slice_sha256: sliceSha256,
      slice_text: sliceText,
      witness_verified: true,
      codepoint_boundary_verified: true,
      utf8_decoder_status: 'FATAL_UTF8_DECODED_CLEAN',
    };
  }

